import { withDocsI18n } from "@/lib/content-i18n/with-docs-i18n"
import { Link } from "@/i18n/navigation"
import type { Metadata } from "next"
import { DeveloperScrollSpyRail } from "@/components/developer-scroll-spy-rail"
import { DeveloperDocPageHeader } from "@/components/developer-doc-page-header"
import { createDocsMetadata } from "@/lib/content-i18n/docs-metadata"
import { resolveLocaleParam, type LocaleParamsProps } from "@/lib/i18n/locale-params"

export async function generateMetadata({ params }: LocaleParamsProps): Promise<Metadata> {
  const locale = await resolveLocaleParam(params)
  return createDocsMetadata(locale, 'reference/security', {
    title: "Security",
    description: "Avana's global invariants, attack scenarios, external dependencies, design decisions and verification approach.",
  })
}

const sections = [
  { id: "overview", title: "Overview" },
  { id: "invariants", title: "Global Invariants" },
  { id: "attacks", title: "Attack Scenarios" },
  { id: "dependencies", title: "External Dependencies" },
  { id: "decisions", title: "Notable Design Decisions" },
  { id: "verification", title: "Verification Approach" },
  { id: "traceability", title: "Traceability" },
]

export default async function ReferenceSecurityPage({ params }: LocaleParamsProps) {
  const locale = await resolveLocaleParam(params)
  return withDocsI18n(locale, "reference/security", (
    <div className="flex min-w-0 flex-col gap-8 xl:flex-row xl:items-start xl:gap-12">
      <div data-developer-doc-export-root className="min-w-0 w-full max-w-3xl flex-1">
        <DeveloperDocPageHeader
          title="Security"
          description="The invariants Avana preserves, the attacks it blocks or bounds, the dependencies it relies on, and how each is verified."
        />
        <section id="overview" className="mb-10"><h2 className="mb-4 type-doc-section-title">Overview</h2><p className="mb-4 type-doc-body">This page summarises Avana&apos;s security specification: the global invariants every transaction preserves, the attack scenarios the design blocks or bounds, the external dependencies it relies on, the main design decisions, and how all of it is verified. Internal identifiers (<code className="type-doc-inline-code">INV-</code>, <code className="type-doc-inline-code">ATTACK-</code>, <code className="type-doc-inline-code">EXT-</code>) are given so reviewers can find each item in the specification.</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Item</th><th className="text-left px-4 py-2 type-doc-subsection-title">Count</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Global invariants</td><td className="px-4 py-2">99 (<code className="type-doc-inline-code">INV-001</code> to <code className="type-doc-inline-code">INV-099</code>) in 11 groups</td></tr><tr><td className="px-4 py-2">Attack scenarios</td><td className="px-4 py-2">197 (<code className="type-doc-inline-code">ATTACK-001</code> to <code className="type-doc-inline-code">ATTACK-197</code>) in 16 categories</td></tr><tr><td className="px-4 py-2">External dependencies</td><td className="px-4 py-2">32 (<code className="type-doc-inline-code">EXT-001</code> to <code className="type-doc-inline-code">EXT-032</code>)</td></tr><tr><td className="px-4 py-2">Design decisions</td><td className="px-4 py-2">400 recorded decisions with their reasons</td></tr><tr><td className="px-4 py-2">Requirements traced</td><td className="px-4 py-2">3,454</td></tr></tbody></table></div></section>
        <section id="invariants" className="mb-10"><h2 className="mb-4 type-doc-section-title">Global Invariants</h2><p className="mb-4 type-doc-body">Each invariant holds at the end of every transaction, in every price state, pause state, breaker state, address-freeze state, sequencer state and governance state, on every chain and for every Hub, CDP Spoke, market and AMM integration, unless it states a narrower scope. The rules that preserve an invariant link to its ID.</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Group</th><th className="text-left px-4 py-2 type-doc-subsection-title">Count</th><th className="text-left px-4 py-2 type-doc-subsection-title">What it covers</th><th className="text-left px-4 py-2 type-doc-subsection-title">Key invariants</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Backing and custody</td><td className="px-4 py-2">9</td><td className="px-4 py-2">Every vault token is backed by credited units of a pledged position, and one position backs one record in one account. The Hub&apos;s vault-token balance, its added assets and the proxies&apos; supplied shares stay equal.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-001</code> supply ≤ credited + pending units; <code className="type-doc-inline-code">INV-005</code> one position, one record; <code className="type-doc-inline-code">INV-007</code> an LPVault returns a position only to its depositor of record or LPVaultSwap; <code className="type-doc-inline-code">INV-058</code> reconcile on exit</td></tr><tr><td className="px-4 py-2">Mint, burn and holders</td><td className="px-4 py-2">10</td><td className="px-4 py-2">Only the AaveAdapter mints and burns, balances move only on the allowed paths, and every seizure debits records largest-first with matching share and supply drops.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-009</code> mint only to a registered proxy; <code className="type-doc-inline-code">INV-011</code> transfer allowlist; <code className="type-doc-inline-code">INV-014</code> seizure check; <code className="type-doc-inline-code">INV-080</code> backing one-sided for any LPVaultSwap</td></tr><tr><td className="px-4 py-2">Accounts and upgradeable custody</td><td className="px-4 py-2">8</td><td className="px-4 py-2">Each PositionProxy is a logic-free account that executes only Adapter calls, there is one proxy per (wallet, CDP Spoke, market), and each upgradeable contract has a stated blast radius.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-018</code> blast radius of upgradeable contracts; <code className="type-doc-inline-code">INV-063</code> Adapter-only proxy access; <code className="type-doc-inline-code">INV-064</code> one proxy per wallet, Spoke and market; <code className="type-doc-inline-code">INV-072</code> account-wide gates for new debt</td></tr><tr><td className="px-4 py-2">Balances and approvals</td><td className="px-4 py-2">2</td><td className="px-4 py-2">No Avana contract keeps an allowance or an Avana-originated balance between transactions, and users approve only one position or an exact amount.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-021</code> zero allowances at the end of every transaction; <code className="type-doc-inline-code">INV-022</code> two kinds of user approval</td></tr><tr><td className="px-4 py-2">Borrowing and pledging</td><td className="px-4 py-2">13</td><td className="px-4 py-2">Borrow-side gates (prices, freshness, Aave flags, drift, caps, breakers, freeze) run before new debt; caps are keyed by Hub; rescue units never support new debt.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-023</code> pre-borrow check; <code className="type-doc-inline-code">INV-025</code> health after borrow; <code className="type-doc-inline-code">INV-028</code> caps; <code className="type-doc-inline-code">INV-029</code> drift check; <code className="type-doc-inline-code">INV-069</code> minimum pledge value; <code className="type-doc-inline-code">INV-082</code> rescue units; <code className="type-doc-inline-code">INV-092</code> caps keyed by Hub</td></tr><tr><td className="px-4 py-2">Liquidation and settlement</td><td className="px-4 py-2">24</td><td className="px-4 py-2">Who can liquidate, how much can be seized, the settlement balance in the debt asset, the Avana fee bound, the flash-source rules, per-asset coverage and the payout escrow.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-030</code> keeper and permissionless entry rules; <code className="type-doc-inline-code">INV-032</code> seizure bounded by debt × bonus; <code className="type-doc-inline-code">INV-035</code> settlement balance; <code className="type-doc-inline-code">INV-037</code> no settlement budget; <code className="type-doc-inline-code">INV-039</code> no in-kind settlement; <code className="type-doc-inline-code">INV-070</code> settlement in the debt asset; <code className="type-doc-inline-code">INV-083</code> oracle minimum on every swap; <code className="type-doc-inline-code">INV-095</code> flash source rules</td></tr><tr><td className="px-4 py-2">Liveness</td><td className="px-4 py-2">9</td><td className="px-4 py-2">Repay, fee collection, debt-free withdrawal and liquidation stay available; pauses, breakers and the address freeze never reach exits or liquidation; one liquidation always fits in one transaction.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-043</code> repay by any payer; <code className="type-doc-inline-code">INV-045</code> debt-free exit; <code className="type-doc-inline-code">INV-046</code> liquidation of an account below 1; <code className="type-doc-inline-code">INV-048</code> keeper floor; <code className="type-doc-inline-code">INV-081</code> stops never reach exits; <code className="type-doc-inline-code">INV-096</code> at most 16 records</td></tr><tr><td className="px-4 py-2">Governance and structure</td><td className="px-4 py-2">13</td><td className="px-4 py-2">Every privileged change goes through the AvanaTimelock with its delays and cancellers; pause-state transitions; admin roles only for the timelock; the Lock has exactly two members.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-051</code> timelock only; <code className="type-doc-inline-code">INV-052</code> immutable contracts; <code className="type-doc-inline-code">INV-068</code> timelock timing; <code className="type-doc-inline-code">INV-084</code> admin roles only for the timelock; <code className="type-doc-inline-code">INV-085</code> address-freeze bounds; <code className="type-doc-inline-code">INV-091</code> the Lock</td></tr><tr><td className="px-4 py-2">Oracle</td><td className="px-4 py-2">4</td><td className="px-4 py-2">The LPOracle never reverts and never returns 0, reports original source timestamps, honours the L2 sequencer gate, and an oracle switch never stops liquidation.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-055</code> never reverts, at least 1; <code className="type-doc-inline-code">INV-056</code> source timestamps; <code className="type-doc-inline-code">INV-098</code> sequencer gate; <code className="type-doc-inline-code">INV-099</code> oracle switch</td></tr><tr><td className="px-4 py-2">System-level economic invariants</td><td className="px-4 py-2">4</td><td className="px-4 py-2">Solvency per debt asset, no zero-risk profit loop, conservative valuation by fair composition, and conservation of each settlement asset across sequences.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-074</code> solvency per debt asset; <code className="type-doc-inline-code">INV-077</code> no zero-risk profit loop; <code className="type-doc-inline-code">INV-078</code> fair composition; <code className="type-doc-inline-code">INV-079</code> settlement-asset conservation</td></tr><tr><td className="px-4 py-2">Aave-side bounds Avana relies on</td><td className="px-4 py-2">3</td><td className="px-4 py-2">Draw caps per debt asset, the standard-Spoke settings and cross-Hub credit lines capped by the funding Hub.</td><td className="px-4 py-2"><code className="type-doc-inline-code">INV-057</code> draw gate; <code className="type-doc-inline-code">INV-093</code> standard-Spoke settings; <code className="type-doc-inline-code">INV-094</code> cross-Hub lines</td></tr></tbody></table></div></section>
        <section id="attacks" className="mb-10"><h2 className="mb-4 type-doc-section-title">Attack Scenarios</h2><p className="mb-4 type-doc-body">The attacker model: flash loans, block-builder access or private order flow, the ability to deploy contracts, holdings of every debt asset and pool token, the roles of borrower, LP, payer or keeper, or control of one compromised key or one hostile upgrade that passed the 5-day timelock delay without any canceller acting. Each scenario lists the calls the attacker would make, the expected protection and a result.</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Category</th><th className="text-left px-4 py-2 type-doc-subsection-title">Scenarios</th><th className="text-left px-4 py-2 type-doc-subsection-title">IDs</th><th className="text-left px-4 py-2 type-doc-subsection-title">What it covers</th><th className="text-left px-4 py-2 type-doc-subsection-title">Examples</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Custody and minting</td><td className="px-4 py-2">16</td><td className="px-4 py-2">001, 003 to 017</td><td className="px-4 py-2">Unbacked vault tokens, duplicate or foreign positions, stray-position returns, donations and rounding on release</td><td className="px-4 py-2">Duplicate LP collateral registration (001); unbacked mint through the minter&apos;s upgrade path (011)</td></tr><tr><td className="px-4 py-2">Vault-token escape and seizure paths</td><td className="px-4 py-2">12</td><td className="px-4 py-2">002, 018 to 028</td><td className="px-4 py-2">Vault tokens leaving the allowed holders, third-party liquidation, receive-shares and hostile LPVaultSwap seizures</td><td className="px-4 py-2">Liquidation outside the authorized route (002); hostile LPVaultSwap debits a healthy account&apos;s records (025)</td></tr><tr><td className="px-4 py-2">Proxies, Adapter, RiskModule and approvals</td><td className="px-4 py-2">11</td><td className="px-4 py-2">029 to 039</td><td className="px-4 py-2">Proxy front-running, gate bypass, hostile Adapter or RiskModule, nonce replay, standing approvals</td><td className="px-4 py-2">Credit-line drain through a malicious AaveAdapter upgrade (032); borrow-nonce replay (036)</td></tr><tr><td className="px-4 py-2">Oracle and price states</td><td className="px-4 py-2">17</td><td className="px-4 py-2">040 to 056</td><td className="px-4 py-2">Price manipulation, TWAP abuse, stale and lagging feeds, common-mode feed errors, disagreement and rounding</td><td className="px-4 py-2">Flash-loan manipulation of the vault-token price (040); common-mode feed error passes the agreement and TWAP checks (051)</td></tr><tr><td className="px-4 py-2">Liquidation griefing and economics</td><td className="px-4 py-2">25</td><td className="px-4 py-2">057 to 081</td><td className="px-4 py-2">Unliquidatable positions, issuer blocklists, gas exhaustion, dust, sandwiching, flash-cost billing and spoofed callbacks</td><td className="px-4 py-2">Unliquidatable position through a reverting payout recipient (057); spoofed flash-loan or swap callback (074)</td></tr><tr><td className="px-4 py-2">Keepers and operations</td><td className="px-4 py-2">5</td><td className="px-4 py-2">082 to 086</td><td className="px-4 py-2">Keeper key theft, keeper outages and wipes, delay bypass for keeper grants, emergency pause used against liquidation</td><td className="px-4 py-2">Bad debt during a keeper outage (083); emergency pause used to halt liquidation (086)</td></tr><tr><td className="px-4 py-2">Caps, deficits and share math</td><td className="px-4 py-2">7</td><td className="px-4 py-2">087 to 091, 095, 096</td><td className="px-4 py-2">Exposure-cap bypass, pool-share denominators, coverage spent outside Avana, share inflation, rounding loops</td><td className="px-4 py-2">Exposure-cap bypass (087); value extraction through rounding loops (096)</td></tr><tr><td className="px-4 py-2">Reentrancy</td><td className="px-4 py-2">3</td><td className="px-4 py-2">092 to 094</td><td className="px-4 py-2">Cross-contract and read-only reentrancy, native ETH payouts</td><td className="px-4 py-2">Cross-contract reentrancy during settlement (092); read-only reentrancy on the Lens or LPOracle (093)</td></tr><tr><td className="px-4 py-2">Governance</td><td className="px-4 py-2">8</td><td className="px-4 py-2">097 to 104</td><td className="px-4 py-2">Timelock and pause abuse, guardian misuse, Aave-side reconfiguration, malicious listings</td><td className="px-4 py-2">Short-delay tightening that halts liquidation (100); exploit through a malicious market listing (104)</td></tr><tr><td className="px-4 py-2">Off-chain, signatures and dependencies</td><td className="px-4 py-2">6</td><td className="px-4 py-2">105 to 110</td><td className="px-4 py-2">Phishing through transaction preparation, spoofed targets, indexer poisoning, supply-chain swaps, signature replay</td><td className="px-4 py-2">Approval phishing through compromised transaction preparation (105); web bundle or manifest supply-chain swap (108)</td></tr><tr><td className="px-4 py-2">Settlement recovery, Aave reserve pauses and persistent disagreement</td><td className="px-4 py-2">3</td><td className="px-4 py-2">111 to 113</td><td className="px-4 py-2">Liquidation at a disputed price, new debt against a paused reserve, the pending-settlement balance</td><td className="px-4 py-2">Liquidation at a disputed price after the disagreement window (111); theft through the pending-settlement balance (113)</td></tr><tr><td className="px-4 py-2">Permissionless liquidation, third-party repay and payout escrow</td><td className="px-4 py-2">6</td><td className="px-4 py-2">114 to 119</td><td className="px-4 py-2">Tiny permissionless liquidations, route sandwiching, third-party repay front-running, escrow claims</td><td className="px-4 py-2">Griefing through tiny permissionless liquidations (114); payout escrow claim by the wrong person (118)</td></tr><tr><td className="px-4 py-2">CDP Spoke implementation and configuration</td><td className="px-4 py-2">2</td><td className="px-4 py-2">120, 121</td><td className="px-4 py-2">Spoke upgrades or listings that reopen third-party seizure</td><td className="px-4 py-2">CDP Spoke upgrade that reopens third-party seizure (120); listing on a Spoke without the required settings (121)</td></tr><tr><td className="px-4 py-2">Adapter custody, immutable proxies, governance timing and multi-asset debt</td><td className="px-4 py-2">16</td><td className="px-4 py-2">122 to 137</td><td className="px-4 py-2">Hostile Adapter upgrades, proxy code changes, debt-asset rallies, stale debt feeds, per-asset coverage, timelock timing</td><td className="px-4 py-2">Hostile AaveAdapter upgrade (122); debt-asset price rally liquidates stable-LP accounts together (128)</td></tr><tr><td className="px-4 py-2">Circuit breakers, address freeze, standby routes, rescue and new liquidation paths</td><td className="px-4 py-2">15</td><td className="px-4 py-2">138 to 152</td><td className="px-4 py-2">Breaker griefing, compromised guardians, standby routes, top-up and deleverage sandwiches, USDT fee switch, admin-role takeover</td><td className="px-4 py-2">Compromised guardian uses address freeze, breakers and the standby switch (139); admin-role grant takeover (152)</td></tr><tr><td className="px-4 py-2">AMM-neutral core, Hubs and chains</td><td className="px-4 py-2">45</td><td className="px-4 py-2">153 to 197</td><td className="px-4 py-2">Range and pricing errors per AMM protocol, cross-Hub lines and squatting, L2 sequencer outages, flash sources, Aave-side halts, payout order, transfer-fee debt assets</td><td className="px-4 py-2">Narrow-range position credited at the market range&apos;s value (153); liquidation on stale prices after an L2 sequencer outage (171)</td></tr></tbody></table></div><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Result</th><th className="text-left px-4 py-2 type-doc-subsection-title">Scenarios</th><th className="text-left px-4 py-2 type-doc-subsection-title">Meaning</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Mitigated</td><td className="px-4 py-2">146</td><td className="px-4 py-2">The named invariants and decisions block the attack (some rows state a narrower scope, for example for the reviewed Adapter).</td></tr><tr><td className="px-4 py-2">Accepted risk</td><td className="px-4 py-2">39</td><td className="px-4 py-2">Residual risk with a named owner and a bound on the loss (for example a hostile upgrade bounded by the 5-day delay and cancellers, or an Aave DAO configuration change).</td></tr><tr><td className="px-4 py-2">Launch condition</td><td className="px-4 py-2">10</td><td className="px-4 py-2">Mitigated once a named check passes before launch, such as a per-pool manipulation-cost study, cap stress tests or a debt-reserve rally test.</td></tr><tr><td className="px-4 py-2">Prevented by the CDP Spoke code</td><td className="px-4 py-2">2</td><td className="px-4 py-2">Third-party liquidation and receive-shares borrowing are closed by the standard Spoke&apos;s own code and the required settings.</td></tr></tbody></table></div></section>
        <section id="dependencies" className="mb-10"><h2 className="mb-4 type-doc-section-title">External Dependencies</h2><p className="mb-4 type-doc-body">Every contract or service outside Avana&apos;s code that Avana relies on, on Ethereum and Base, with what Avana assumes and what happens if the assumption breaks. Each entry also names the rule that limits the damage.</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">ID</th><th className="text-left px-4 py-2 type-doc-subsection-title">Dependency</th><th className="text-left px-4 py-2 type-doc-subsection-title">What Avana assumes</th><th className="text-left px-4 py-2 type-doc-subsection-title">What happens if it fails</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-001</code></td><td className="px-4 py-2">Aave V4 Hubs</td><td className="px-4 py-2">Vault-token assets on exactly one CDP Spoke plus the fee receiver, zero draw caps on them, shares equal to assets; draw caps per (Hub, asset) within the credit line, raised above 0 only after coverage is funded</td><td className="px-4 py-2">Share drift or a second Spoke breaks backing; a Hub halt stops repay, withdraw and liquidation of that Spoke until the DAO lifts it, while fee collection and deficit coverage continue</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-002</code></td><td className="px-4 py-2">Aave V4 CDP Spokes (standard Spoke)</td><td className="px-4 py-2">The listing sets receive-shares off, a liquidation fee of 0 or paid to Avana, no reinvestment controller and non-borrowable vault-token reserves, so only LPVaultSwap can complete a liquidation</td><td className="px-4 py-2">A configuration change could let a third party take supply shares with no token transfer; the drift check stops new activity and the case is an accepted Aave DAO risk</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-003</code></td><td className="px-4 py-2">AaveOracle and debt price sources</td><td className="px-4 py-2">AaveOracle applies no staleness check, so freshness is Avana&apos;s job; Avana&apos;s oracles never revert and serve at least 1</td><td className="px-4 py-2">A reverting or zero price would freeze accounts; a stale debt price blocks borrowing for accounts holding that debt and delays liquidation repaying it</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-004</code></td><td className="px-4 py-2">Lend Spoke and Coverage Spokes</td><td className="px-4 py-2">Only listed Spokes eliminate deficits; each Coverage Spoke enforces its allowlist; reserve withdrawals need DAO approval after the withdrawal delay</td><td className="px-4 py-2">Coverage spent on another Spoke or asset, deficits left uncovered, or a recalled line that stops new borrowing (repay continues)</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-005</code></td><td className="px-4 py-2">Aave governance roles</td><td className="px-4 py-2">Changes follow the required settings; a Guardian reserve pause is used only for exploits and lifted within the 48-hour incident window</td><td className="px-4 py-2">A change outside Avana&apos;s timelock or a reserve pause with no expiry can stop liquidation of the affected accounts</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-031</code></td><td className="px-4 py-2">Aave V4 on Base</td><td className="px-4 py-2">The same pinned code with the required settings; GHO on Base is the CCIP burn and mint token</td><td className="px-4 py-2">A Base deployment from other code breaks the Hub and Spoke assumptions on Base only; Base payloads arrive after the Ethereum vote</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-030</code></td><td className="px-4 py-2">Aave V3 Pool flashLoan</td><td className="px-4 py-2">Premium rounded up, 5 bps at deployment, 0 for a <code className="type-doc-inline-code">FLASH_BORROWER</code>; premium, idle liquidity and reserve flags read at each call</td><td className="px-4 py-2">A paused reserve, a premium above the ceiling or short liquidity stops flash-funded liquidation of that asset; the keeper funds it itself</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-012</code></td><td className="px-4 py-2">Aave V3 ACLManager FLASH_BORROWER role</td><td className="px-4 py-2">Granted by AIP to the flash source and not revoked</td><td className="px-4 py-2">Without it the premium is non-zero; above <code className="type-doc-inline-code">maxFlashFeeBps</code> flash-funded liquidation reverts before <code className="type-doc-inline-code">liquidationCall</code></td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-011</code></td><td className="px-4 py-2">GHO FlashMinter (not used)</td><td className="px-4 py-2">None</td><td className="px-4 py-2">None for Avana</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-006</code></td><td className="px-4 py-2">Uniswap v3 NonfungiblePositionManager</td><td className="px-4 py-2"><code className="type-doc-inline-code">increaseLiquidity</code> is permissionless; removal and collection need owner or approval; approvals clear on transfer; not upgradeable</td><td className="px-4 py-2">A strict liquidity check would let donations block exits; an approval would let a third party drain positions; uncapped collection would take depositor fees</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-007</code></td><td className="px-4 py-2">Uniswap v3 factory and listed pools</td><td className="px-4 py-2">Pools are immutable; observation history covers the TWAP window; listed pools meet the manipulation-cost depth</td><td className="px-4 py-2">Thin pools make the TWAP check cheap to trip (blocks new risk only); a broken pool makes fee collection and unwinds revert</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-028</code></td><td className="px-4 py-2">Aerodrome Slipstream position manager, factory and pools</td><td className="px-4 py-2">Gauge-staked positions are owned by the gauge and cannot be pledged; each market binds one factory and position-manager generation</td><td className="px-4 py-2">A v3 ABI used on Slipstream misreads pool data; a wrong generation binds the wrong contracts; a TWAP buffer sized for 12 s blocks covers a sixth of the time on Base</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-032</code></td><td className="px-4 py-2">Uniswap v2, Curve StableSwap-NG, Balancer and Uniswap v4</td><td className="px-4 py-2">Supported by the core and listed only after their readiness guards pass; reads check each pool&apos;s reentrancy lock</td><td className="px-4 py-2">Read-only reentrancy or same-transaction manipulation inflates a quote; a v4 hook blocks or taxes unwinds</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-008</code></td><td className="px-4 py-2">Chainlink primary feeds</td><td className="px-4 py-2">A new round on each deviation, otherwise once per heartbeat (stablecoin heartbeats 82,800 to 86,400 s)</td><td className="px-4 py-2">A stale feed moves the market to Cached and then Expired: borrowing stops, its seizure waits, and from Expired it counts at 1 in health factors</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-009</code></td><td className="px-4 py-2">Chainlink alternate routes</td><td className="px-4 py-2">The two routes share no intermediate feed; the agreement tolerance covers both deviation thresholds plus a margin</td><td className="px-4 py-2">A shared feed creates a common-mode error; a faulty route causes a disagreement that pauses the market&apos;s seizure until the routes agree or a standby replaces one</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-020</code></td><td className="px-4 py-2">Debt-asset feeds through the DebtOracle</td><td className="px-4 py-2">Each leg&apos;s age limit is its own heartbeat plus margin; routes track the asset&apos;s market price</td><td className="px-4 py-2">Both routes stale: borrowing of that debt stops and the debt counts at its stress price in health factors</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-024</code></td><td className="px-4 py-2">DebtOracle feeds and standby routes</td><td className="px-4 py-2">The standby passes the listing checks of the slot it replaces and is independent of it</td><td className="px-4 py-2">A stale or shared standby does not restore the price; a compromised guardian&apos;s switch lasts until the Aave governance executor cancels it</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-025</code></td><td className="px-4 py-2">Chainlink proxy phases</td><td className="px-4 py-2">Aggregator upgrades keep past phases readable; a new phase starts its round IDs at 1</td><td className="px-4 py-2">Without the phase rule an outage that ended on an aggregator upgrade gives no gap evidence and the grace window never opens</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-029</code></td><td className="px-4 py-2">L2 sequencer uptime feed (Base)</td><td className="px-4 py-2">Updated from L1, so it reports an outage while Base blocks are not produced</td><td className="px-4 py-2">Without the gate, borrows on pre-outage prices and liquidations at the first post-outage price are unsafe for users who could not reach the chain</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-010</code></td><td className="px-4 py-2">GHO token</td><td className="px-4 py-2">No transfer fee, hooks or blocklist; GHO debt valued at $1; GHO debt on Base sized to Base flash liquidity</td><td className="px-4 py-2">A behaviour change breaks delta accounting; a GHO premium or discount shifts liquidation economics; thin GHO on Base limits liquidation size</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-013</code></td><td className="px-4 py-2">GHO Stability Modules (Ethereum)</td><td className="px-4 py-2">GHO governance can freeze, seize or re-cap a GSM; buy-side liquidity can be negligible</td><td className="px-4 py-2">A GSM backup leg reverts; with both routes failing the liquidation reverts until a route works again</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-014</code></td><td className="px-4 py-2">Sky LitePSM and the DAI–USDS converter (Ethereum)</td><td className="px-4 py-2">Fee and headroom within the slippage bound</td><td className="px-4 py-2">A paused or exhausted PSM</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-015</code></td><td className="px-4 py-2">DEX swap routes</td><td className="px-4 py-2">A route never uses the market&apos;s own pool; depth meets the published threshold for a one-sided unwind; primary and backup share no pool</td><td className="px-4 py-2">Sandwiching or thin depth lowers proceeds; a leg below its minimum reverts and LPVaultSwap tries the backup</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-021</code></td><td className="px-4 py-2">Swap routes into each debt asset</td><td className="px-4 py-2">Depth meets its threshold for the largest liquidation the caps allow; routes are not upgradeable</td><td className="px-4 py-2">Proceeds below the flash repayment plus floor need the caller&apos;s top-up; both routes failing reverts the liquidation</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-016</code></td><td className="px-4 py-2">Credit-line suppliers</td><td className="px-4 py-2">Only idle liquidity can be withdrawn; a recall lowers draw caps to 0; suppliers take deficits beyond first-loss coverage</td><td className="px-4 py-2">Recall or exhaustion stops new borrowing of that asset; repay, withdrawals and liquidation continue</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-022</code></td><td className="px-4 py-2">Cross-Hub credit lines</td><td className="px-4 py-2">The funding Hub owns the cap and its liquidity covers it</td><td className="px-4 py-2">Caps set by the borrowing Hub, or a funding-Hub pause that does not reach foreign Spokes, would let them draw past the line</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-017</code></td><td className="px-4 py-2">Pool tokens and debt assets</td><td className="px-4 py-2">No fee-on-transfer, rebasing, hooks or false-returning transfer at listing; USDC and USDT issuer controls accepted with monitoring</td><td className="px-4 py-2">An issuer pause stops transfers of the token; a blocklist of LPVaultSwap stops routed settlement of the affected markets until an upgrade</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-026</code></td><td className="px-4 py-2">Issuer probes paused() and basisPointsRate()</td><td className="px-4 py-2">The view reflects the token&apos;s transfer behaviour in the same block</td><td className="px-4 py-2">A probe that returns true, a non-zero rate or fails trips the issuer breaker and stops new risk in that token</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-018</code></td><td className="px-4 py-2">OpenZeppelin Contracts</td><td className="px-4 py-2"><code className="type-doc-inline-code">TimelockController</code> holds its own admin role; <code className="type-doc-inline-code">cancel</code> reaches only pending operations; UUPS upgrades only through <code className="type-doc-inline-code">upgradeToAndCall</code></td><td className="px-4 py-2">An admin outside the timelock would allow a role grant without delay; an uninitialized implementation could be initialized by anyone</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-023</code></td><td className="px-4 py-2">WETH token</td><td className="px-4 py-2">No blocklist, fee or hooks; returns true on transfer</td><td className="px-4 py-2">No token failure; a WETH rally raises the debt of stable-LP accounts and can make them liquidatable together</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-019</code></td><td className="px-4 py-2">Block builders, private submission and sequencers</td><td className="px-4 py-2">At least one independent submission path per keeper operator per chain</td><td className="px-4 py-2">Censorship or delay of liquidations; sandwiching of swap legs; a Base sequencer outage stops ordinary inclusion</td></tr><tr><td className="px-4 py-2"><code className="type-doc-inline-code">EXT-027</code></td><td className="px-4 py-2">Safe guard and delay module</td><td className="px-4 py-2">Reviewed guard and module code; signers on dedicated hardware wallets; the Aave governance executor as second proposer</td><td className="px-4 py-2">A removed guard lets the Safe call contracts directly (no Avana contract accepts it); a faulty delay module lets a compromised quorum replace owners; a lost quorum stops proposals</td></tr></tbody></table></div></section>
        <section id="decisions" className="mb-10"><h2 className="mb-4 type-doc-section-title">Notable Design Decisions</h2><p className="mb-4 type-doc-body">A selection from the 400 recorded design decisions. Each records its final resolution and the risk it controls; replaced decisions keep their rows and name their replacement.</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Decision</th><th className="text-left px-4 py-2 type-doc-subsection-title">Resolution</th><th className="text-left px-4 py-2 type-doc-subsection-title">Reason</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">AMM-neutral custody</td><td className="px-4 py-2">One immutable LPVault per AMM protocol per chain implements a common interface; the core calls no AMM protocol contract.</td><td className="px-4 py-2">A new AMM protocol adds a vault, a pricing library and an LPOracle implementation, with no change to the ledger, factory or Lock.</td></tr><tr><td className="px-4 py-2">Instance scope</td><td className="px-4 py-2">One set of per-chain contracts (one Adapter, one LPVaultSwap, one ledger) serves every Hub of the chain.</td><td className="px-4 py-2">Per-Hub copies would run the same code under the same keys without a smaller blast radius, and one ledger keyed by Hub keeps Hub-wide caps from multiplying.</td></tr><tr><td className="px-4 py-2">Account isolation</td><td className="px-4 py-2">One PositionProxy per wallet, CDP Spoke and market; several markets per Spoke.</td><td className="px-4 py-2">Several markets in one account let one stale oracle liquidate healthy collateral; one account per market gives full isolation with fewer governance actions.</td></tr><tr><td className="px-4 py-2">Immutable, logic-free proxies</td><td className="px-4 py-2">PositionProxies have one Adapter-only function and no upgrade; all account logic lives in the Adapter.</td><td className="px-4 py-2">Aave V4 has no position transfer, so proxies cannot be migrated; a fix reaches every account through one timelocked Adapter upgrade.</td></tr><tr><td className="px-4 py-2">Immutable custody</td><td className="px-4 py-2">LPVaults, Collateralization, vault tokens, the factory, the Lock and the escrow are immutable; gates, prices and settlement logic are upgradeable.</td><td className="px-4 py-2">No upgrade can change who receives a position or how backing is counted, while code that needs tuning stays behind one watched upgrade path.</td></tr><tr><td className="px-4 py-2">Standard Spoke with three required settings</td><td className="px-4 py-2">Every CDP Spoke is an unmodified Aave V4 Spoke; receive-shares off, liquidation fee 0 or paid to Avana, no reinvestment controller.</td><td className="px-4 py-2">While these hold, the vault token&apos;s transfer rule is the only gate needed; a drift alarm cannot stop a seizure in the same block, so the settings are checked on every pledge and borrow.</td></tr><tr><td className="px-4 py-2">Settlement in the debt asset</td><td className="px-4 py-2">LPVaultSwap flash-borrows the debt asset itself and pays out in it.</td><td className="px-4 py-2">Base has no GHO FlashMinter and Aave V4 has no flash loan; this removes the buy and sell-back legs and their slippage.</td></tr><tr><td className="px-4 py-2">Flash source never lends a Hub&apos;s liquidity</td><td className="px-4 py-2">A flash source whose lender is any Hub registered on the chain is refused, at setup and at every loan.</td><td className="px-4 py-2">Comparing with one Hub missed sources whose Spoke draws from that Hub.</td></tr><tr><td className="px-4 py-2">No settlement budget</td><td className="px-4 py-2">The caller sizes the repayment for Aave&apos;s dust rule and pays any rounding gap.</td><td className="px-4 py-2">The budget needed funding, windows, floors and a breaker, each a liveness surface, to pay a few base units.</td></tr><tr><td className="px-4 py-2">No in-kind settlement</td><td className="px-4 py-2">Every liquidation settles in the debt asset or reverts; the escrow holds only refused payouts.</td><td className="px-4 py-2">Route-depth listing rules, standby routes, the shortfall top-up and the Avana Umbrella already cover a total route failure.</td></tr><tr><td className="px-4 py-2">No on-chain health floor</td><td className="px-4 py-2">Borrowing needs Aave&apos;s health factor 1.00 and the caller&apos;s limit; the Lens recommends 1.10.</td><td className="px-4 py-2">A floor above 1.00 limits borrowers without bounding Avana&apos;s loss, which caps, the bonus and the First-Loss Reserve bound.</td></tr><tr><td className="px-4 py-2">No minimum debt</td><td className="px-4 py-2">Any amount above 0 may be borrowed; Avana&apos;s keepers liquidate every account and Avana pays the gas.</td><td className="px-4 py-2">Small debts arise anyway from partial repays and liquidations; a small liquidation is a bounded operating cost.</td></tr><tr><td className="px-4 py-2">Record cap of 16</td><td className="px-4 py-2">At most 16 open records per account and market.</td><td className="px-4 py-2">Aave&apos;s dust rule can force a whole-account seizure in one call; 16 records cost at most 5.15M gas, under half the per-transaction limit.</td></tr><tr><td className="px-4 py-2">Breakers stop new activity only</td><td className="px-4 py-2">Oracle and peg breaches and deficits block new risk; price drops, seizures and route failures are alerts.</td><td className="px-4 py-2">A reverted call cannot persist a counter and counters can be gamed; actions that reduce risk keep working, so a breaker never turns an incident into bad debt.</td></tr><tr><td className="px-4 py-2">Pool-share gate off by default</td><td className="px-4 py-2">No default limit on Avana&apos;s share of a pool; a cap applies only where a listing sets one.</td><td className="px-4 py-2">Removing liquidity has no price impact and proceeds can use any approved route; liquidation safety comes from route depth and draw caps.</td></tr><tr><td className="px-4 py-2">Liquidation gated by the seized and repaid reserves</td><td className="px-4 py-2">Liquidation needs fresh prices only for the market seized and the debt repaid.</td><td className="px-4 py-2">An account-wide gate let one small failing position shield every other market of the account from liquidation.</td></tr><tr><td className="px-4 py-2">Address freeze</td><td className="px-4 py-2">Guardians can freeze an address at once (at most 20 per day); unfreezing needs the timelock at the normal delay.</td><td className="px-4 py-2">It stops an exploiter&apos;s new exposure in minutes without pausing everyone, while exits and liquidation stay outside the freeze.</td></tr><tr><td className="px-4 py-2">Reconcile on exit</td><td className="px-4 py-2">Units missing from a proxy after an unsettled seizure are debited on the next exit and moved to the pending balance.</td><td className="px-4 py-2">A faulty LPVaultSwap could otherwise leave positions stuck and vault tokens without known backing.</td></tr><tr><td className="px-4 py-2">Self-administered timelock with a delay floor</td><td className="px-4 py-2">The AvanaTimelock holds its own admin role; normal delay 5 days, never below 4; the short-delay list is a fixed allowlist.</td><td className="px-4 py-2">Nobody can shorten a delay or grant a role without waiting in public, and borrowers can exit before any upgrade lands.</td></tr><tr><td className="px-4 py-2">Debt assets beyond GHO</td><td className="px-4 py-2">USDC, USDT and WETH become debt reserves only when funding, caps, price source and both swap routes pass.</td><td className="px-4 py-2">No asset is borrowable unless Avana can liquidate it inside one transaction.</td></tr><tr><td className="px-4 py-2">Cross-Hub credit lines off at launch</td><td className="px-4 py-2">Fully specified, with the funding Hub owning the cap, and disabled per chain.</td><td className="px-4 py-2">Simulation showed no launch benefit, and a register per funding Hub keeps foreign draws within that Hub&apos;s coverage.</td></tr><tr><td className="px-4 py-2">No fee on borrow interest</td><td className="px-4 py-2">Avana&apos;s on-chain revenue is its share of liquidation surplus; the app fee is charged outside the contracts.</td><td className="px-4 py-2">A fee on interest would make the debt a borrower sees differ from Aave&apos;s; keeping the app fee off-chain keeps it out of the audited code and every account&apos;s health.</td></tr><tr><td className="px-4 py-2">Spoke liquidation settings are guidance</td><td className="px-4 py-2">Target health factor 1.10 and minimum bonus of at least 2% are Avana&apos;s recommendation; the Aave DAO decides.</td><td className="px-4 py-2">The Spoke configuration belongs to the Aave DAO; Avana sizes from what it set and stops new activity if it drifts.</td></tr><tr><td className="px-4 py-2">First-loss reserve size set in the funding ARFC</td><td className="px-4 py-2">The coverage rule is fixed; the ratio and minimum are set with the Aave service providers.</td><td className="px-4 py-2">The rule protects lenders at every level, and the level depends on the credit line the providers accept.</td></tr><tr><td className="px-4 py-2">No idle-collateral mechanism</td><td className="px-4 py-2">A debt-free account&apos;s charge stays in the market&apos;s regular cap budget.</td><td className="px-4 py-2">The idle bucket added state and a permissionless mover for a griefing case that costs the attacker its own capital.</td></tr><tr><td className="px-4 py-2">CoW Swap not used</td><td className="px-4 py-2">Routes are fixed on-chain at listing.</td><td className="px-4 py-2">The flash loan must be repaid in the same transaction, and CoW orders settle later in solver batches.</td></tr></tbody></table></div></section>
        <section id="verification" className="mb-10"><h2 className="mb-4 type-doc-section-title">Verification Approach</h2><p className="mb-4 type-doc-body">Avana is verified in two stages. Spec-stage checks model the design itself: the formulas, the state machine across contracts and the economics. Implementation-stage checks prove the same rules on the Solidity. Every critical requirement has at least one verification method, every check links to the requirements it verifies, and every failed check becomes a finding in the register.</p><h3 className="mb-2 type-doc-subsection-title">Spec-stage results (recorded 10 November 2026)</h3><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Check</th><th className="text-left px-4 py-2 type-doc-subsection-title">What it covers</th><th className="text-left px-4 py-2 type-doc-subsection-title">Result</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Traceability (<code className="type-doc-inline-code">trace.py</code>)</td><td className="px-4 py-2">Links every requirement to the checks that verify it; a lock file records each requirement&apos;s accepted text, so an edit must be re-verified before it is accepted again</td><td className="px-4 py-2">3,454 requirements traced, 0 errors</td></tr><tr><td className="px-4 py-2">Z3</td><td className="px-4 py-2">Every formula in exact integers at Solidity bit widths: units, oracle math and price states, Aave V4 health factor and liquidation sizing ported from the pinned Aave V4 commit, recovery floor, waterfall, coverage, timelock timing, and LP pricing per AMM protocol; every worked example recomputed</td><td className="px-4 py-2">45 scripts, 825 checks: 616 proved, 104 computed exactly, 105 counterexamples searched for on purpose; every result matches its recorded value</td></tr><tr><td className="px-4 py-2">SymPy</td><td className="px-4 py-2">Each formula equals the rule it implements, exactly and before rounding</td><td className="px-4 py-2">10 scripts, 240 checks: 239 consistent, 1 deliberate wrong reading</td></tr><tr><td className="px-4 py-2">Hypothesis</td><td className="px-4 py-2">Generated action sequences against an executable integer model of Avana, Aave V4 and Uniswap v3, with solvency per debt asset checked after every step</td><td className="px-4 py-2">82 tests, 82 pass</td></tr><tr><td className="px-4 py-2">Quint</td><td className="px-4 py-2">Cross-contract state machine with honest and hostile components, and a multi-Hub, multi-Spoke topology model</td><td className="px-4 py-2">70 deterministic scenarios pass (50 system, 20 topology); no violation of the 43 system and 15 topology invariants in the recorded simulator runs</td></tr><tr><td className="px-4 py-2">Simulations</td><td className="px-4 py-2">Economic stress: depegs, oracle outages, correlated drops, keeper outages, gas and dust, route stress, interest; a 1,000-user, 90-day simulation with six stress episodes</td><td className="px-4 py-2">Seeded and reproducible; the 1,000-user run made 572,608 invariant checks with 0 violations, 98 liquidations and $0 bad debt</td></tr><tr><td className="px-4 py-2">Internal formal verification</td><td className="px-4 py-2">Custody, control (access, timelock, pause, gates, parameters, oracle, upgrades, breakers) and liquidation areas</td><td className="px-4 py-2">Custody: every check verified; control: 180 checks, 168 verified, 6 under a bounded model, 6 Quint invariants with no violation; liquidation: 271 checks pass</td></tr></tbody></table></div><p className="mb-4 type-doc-body">Bounded and random checks do not establish correctness beyond their modelled depth, and mathematical correctness is not economic correctness: pool risk factors, caps and the incident window rest on the simulations and on the Aave V4 risk service providers. These checks cover the specification and the contract interfaces; the implementation-stage checks below prove the same rules on the Solidity.</p><h3 className="mb-2 type-doc-subsection-title">Implementation-stage verification</h3><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Method</th><th className="text-left px-4 py-2 type-doc-subsection-title">What runs</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Foundry tests</td><td className="px-4 py-2">287 tests (<code className="type-doc-inline-code">TEST-001</code> to <code className="type-doc-inline-code">TEST-287</code>): unit, access-control, fuzz, boundary, differential, invariant, fork, hostile-component, deployment-check, keeper, off-chain, gas and security-tooling tests. The invariant suite asserts every global invariant after each step of borrowers, outside LPs, keepers, permissionless liquidators, a flash-loan attacker, a pool manipulator, a lender, the guardians and the timelock.</td></tr><tr><td className="px-4 py-2">Hostile-component tests</td><td className="px-4 py-2">Hostile Adapter, LPVaultSwap, RiskModule, MarketRegistry and ParameterStore implementations installed through the real timelock path at the 5-day delay, each shown to stay within its stated blast radius.</td></tr><tr><td className="px-4 py-2">Formal properties</td><td className="px-4 py-2">86 implementation-stage properties (<code className="type-doc-inline-code">PROP-001</code> to <code className="type-doc-inline-code">PROP-097</code>, with gaps): most in Certora CVL over all reachable states, the rest as Halmos symbolic Foundry tests, and SMTChecker proofs (CHC engine) of the absence of overflow, underflow, division by zero and failing asserts in the immutable contracts and the oracle, settlement and route code.</td></tr><tr><td className="px-4 py-2">Fast security tier (every push and pull request)</td><td className="px-4 py-2"><code className="type-doc-inline-code">forge fmt</code> and <code className="type-doc-inline-code">forge lint</code>, a warnings-denied build, solhint 6.2.5, Slither 0.11.6 with its upgradeability check, Aderyn 0.6.8 and the file-size checks; gates every merge.</td></tr><tr><td className="px-4 py-2">Slow security tier (nightly and before every release)</td><td className="px-4 py-2">Echidna 2.3.3 and Medusa 1.5.1 on every property harness, Halmos 0.3.3, hevm 0.58.0 on harness assertions and runtime bytecode, and Mythril 0.24.8 on the runtime code of every contract; gates every release tag and timelock-scheduled upgrade.</td></tr></tbody></table></div><p className="mb-4 type-doc-body">Two tools named in earlier plans are not used: MythX shut down, so Mythril runs locally and no step sends code to an external service; Manticore is archived, so hevm and Halmos carry symbolic execution.</p></section>
        <section id="traceability" className="mb-10"><h2 className="mb-4 type-doc-section-title">Traceability</h2><p className="mb-4 type-doc-body"><code className="type-doc-inline-code">trace.py</code> builds the requirement, check and implementation matrix. It fails on a duplicate ID, a link to an undefined ID, or a requirement whose text changed since it was last accepted; in strict mode it also fails when a requirement has no check, and, once the code exists, when a requirement has no test, property or source link. Each row of the matrix has one status:</p><div className="mb-6 overflow-x-auto"><table className="type-doc-table"><thead className="bg-gray-50"><tr><th className="text-left px-4 py-2 type-doc-subsection-title">Status</th><th className="text-left px-4 py-2 type-doc-subsection-title">Meaning</th></tr></thead><tbody className="divide-y divide-gray-200"><tr><td className="px-4 py-2">Unverified</td><td className="px-4 py-2">No check links to the requirement yet.</td></tr><tr><td className="px-4 py-2">Modelled</td><td className="px-4 py-2">Spec-stage checks only (Z3, SymPy, Quint, Hypothesis, simulations).</td></tr><tr><td className="px-4 py-2">Planned (prover)</td><td className="px-4 py-2">A Certora, Halmos or SMTChecker property names the requirement, and the prover has not passed it yet.</td></tr><tr><td className="px-4 py-2">Verified</td><td className="px-4 py-2">Spec-stage checks plus a Foundry test or a property the prover passed.</td></tr><tr><td className="px-4 py-2">Changed — re-verify</td><td className="px-4 py-2">The requirement&apos;s text changed since its checks were accepted; the checks must be rerun and the change accepted.</td></tr></tbody></table></div><p className="mb-4 type-doc-body">Findings and their statuses are tracked on the <Link href="/developers/reference/audits" className="text-type-accent hover:underline">Audits</Link> page.</p></section>
      </div>
      <DeveloperScrollSpyRail
        sections={sections}
        pageSummary="Security reference: 99 global invariants, 197 attack scenarios in 16 categories, 32 external dependencies, notable design decisions and the verification plan."
        sectionColor="slate"
      />
    </div>
  ))
}
